/**
 * Suspending and reinstating members: the guards, the last-owner rule and
 * everything a suspended member is cut off from.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as commentService from "@/server/services/comment-service";
import { buildDigest, listDigestRecipients } from "@/server/services/digest-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { notify, listNotifications } from "@/server/services/notification-service";
import * as orgService from "@/server/services/organization-service";
import * as sessionService from "@/server/services/session-service";
import { NotFoundError } from "@/server/services/_support";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import { recomputeUsage } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { MemberId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Role } from "@/types/member";

let cleanup: () => void;
let detachAudit: Unsubscribe;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

async function memberOf(tenant: Tenant, role: Role) {
  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error(`fixture ${role} missing`);
  return member;
}

async function suspend(tenant: Tenant, role: Role) {
  const member = await memberOf(tenant, role);
  return memberService.suspendMember(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: member.id,
  });
}

async function statusOf(tenant: Tenant, role: Role) {
  return (await memberOf(tenant, role)).status;
}

async function notificationsFor(tenant: Tenant, userId: UserId) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    limit: 50,
    cursor: null,
  });
  return page.items;
}

const PAYLOAD = {
  title: "Hello",
  body: "Hello",
  href: "/x",
  actorId: null,
};

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachAudit = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

describe("suspendMember / reinstateMember", () => {
  it("suspends and reinstates, returning the stored member", async () => {
    const tenant = await createTenant("susp-basic");
    const suspended = await suspend(tenant, "member");

    expect(suspended.status).toBe("suspended");
    expect(suspended.role).toBe("member");
    expect(await statusOf(tenant, "member")).toBe("suspended");

    const reinstated = await memberService.reinstateMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: suspended.id,
    });
    expect(reinstated.status).toBe("active");
    expect(await statusOf(tenant, "member")).toBe("active");
  });

  it("publishes member.suspended / member.reinstated and audits them", async () => {
    const tenant = await createTenant("susp-events");
    const suspendedEvents = capture("member.suspended");
    const reinstatedEvents = capture("member.reinstated");

    const member = await suspend(tenant, "viewer");
    await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    expect(suspendedEvents).toHaveLength(1);
    expect(suspendedEvents[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.owner,
      memberId: member.id,
      userId: tenant.userIds.viewer,
    });
    expect(reinstatedEvents).toHaveLength(1);
    expect(reinstatedEvents[0]).toMatchObject({ memberId: member.id });

    const page = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["member.suspended", "member.reinstated"],
      subjectKind: "member",
      limit: 25,
      cursor: null,
    });
    expect(page.items.map((row) => row.action).sort()).toEqual([
      "member.reinstated",
      "member.suspended",
    ]);
    for (const row of page.items) {
      expect(row).toMatchObject({
        subjectKind: "member",
        subjectId: member.id,
        actorId: tenant.userIds.owner,
      });
    }
  });

  it("is a silent no-op when the status already matches", async () => {
    const tenant = await createTenant("susp-idempotent");
    const suspendedEvents = capture("member.suspended");
    const reinstatedEvents = capture("member.reinstated");
    const member = await memberOf(tenant, "member");
    const input = { orgId: tenant.org.id, memberId: member.id };

    const again = await memberService.reinstateMember(tenant.actors.owner, input);
    expect(again.status).toBe("active");
    expect(reinstatedEvents).toHaveLength(0);

    await memberService.suspendMember(tenant.actors.owner, input);
    const twice = await memberService.suspendMember(tenant.actors.owner, input);
    expect(twice.status).toBe("suspended");
    expect(suspendedEvents).toHaveLength(1);
  });

  describe("guards", () => {
    it("refuses an org outside the actor's organization", async () => {
      const tenant = await createTenant("susp-scope-a");
      const other = await createTenant("susp-scope-b");
      const target = await memberOf(other, "member");

      await expect(
        memberService.suspendMember(tenant.actors.owner, {
          orgId: other.org.id,
          memberId: target.id,
        }),
      ).rejects.toBeInstanceOf(TenantScopeError);
      expect(await statusOf(other, "member")).toBe("active");
    });

    it("throws NotFoundError for an unknown member or one from another org", async () => {
      const tenant = await createTenant("susp-missing-a");
      const other = await createTenant("susp-missing-b");
      const foreign = await memberOf(other, "member");

      for (const memberId of ["no-such-member" as MemberId, foreign.id]) {
        await expect(
          memberService.suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId }),
        ).rejects.toBeInstanceOf(NotFoundError);
        await expect(
          memberService.reinstateMember(tenant.actors.owner, { orgId: tenant.org.id, memberId }),
        ).rejects.toBeInstanceOf(NotFoundError);
      }
    });

    it("throws NotFoundError for a member that was removed", async () => {
      const tenant = await createTenant("susp-removed");
      const target = await memberOf(tenant, "viewer");
      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
      const events = capture("member.suspended");

      await expect(
        memberService.suspendMember(tenant.actors.owner, {
          orgId: tenant.org.id,
          memberId: target.id,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        memberService.reinstateMember(tenant.actors.owner, {
          orgId: tenant.org.id,
          memberId: target.id,
        }),
      ).rejects.toBeInstanceOf(NotFoundError);
      expect(events).toHaveLength(0);
    });

    it("needs the member:remove permission", async () => {
      const tenant = await createTenant("susp-permission");
      const target = await memberOf(tenant, "viewer");
      const events = capture("member.suspended");

      await expect(
        memberService.suspendMember(tenant.actors.member, {
          orgId: tenant.org.id,
          memberId: target.id,
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
      expect(await statusOf(tenant, "viewer")).toBe("active");
      expect(events).toHaveLength(0);
    });

    it("refuses self-suspension and self-reinstatement", async () => {
      const tenant = await createTenant("susp-self");
      const admin = await memberOf(tenant, "admin");
      const events = capture("member.suspended");

      await expect(
        memberService.suspendMember(tenant.actors.admin, {
          orgId: tenant.org.id,
          memberId: admin.id,
        }),
      ).rejects.toThrow();
      expect(await statusOf(tenant, "admin")).toBe("active");

      await suspend(tenant, "admin");
      await expect(
        memberService.reinstateMember(tenant.actors.admin, {
          orgId: tenant.org.id,
          memberId: admin.id,
        }),
      ).rejects.toThrow();
      expect(await statusOf(tenant, "admin")).toBe("suspended");
      expect(events).toHaveLength(1);
    });

    it("refuses acting on a member whose role outranks the actor's", async () => {
      const tenant = await createTenant("susp-rank");
      const owner = await memberOf(tenant, "owner");
      const events = capture("member.suspended");

      await expect(
        memberService.suspendMember(tenant.actors.admin, {
          orgId: tenant.org.id,
          memberId: owner.id,
        }),
      ).rejects.toThrow();
      expect(await statusOf(tenant, "owner")).toBe("active");
      expect(events).toHaveLength(0);

      // An admin may act on their own rank and below.
      const peer = await createTenant("susp-rank-peer");
      const peerAdmin = await memberOf(peer, "admin");
      const done = await memberService.suspendMember(peer.actors.owner, {
        orgId: peer.org.id,
        memberId: peerAdmin.id,
      });
      expect(done.status).toBe("suspended");

      await expect(
        memberService.reinstateMember(tenant.actors.admin, {
          orgId: tenant.org.id,
          memberId: (await suspend(tenant, "owner").catch(() => owner)).id,
        }),
      ).resolves.toBeDefined();
    });
  });

  describe("the last-owner rule", () => {
    it("counts only owners who are not suspended", async () => {
      const tenant = await createTenant("susp-owners");
      const owner = await memberOf(tenant, "owner");
      const admin = await memberOf(tenant, "admin");

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "owner",
      });
      await suspend(tenant, "admin"); // owner #2 suspended

      // The only unsuspended owner cannot be suspended, demoted or removed.
      const stranger = { ...tenant.actors.owner, userId: tenant.userIds.viewer };
      await expect(
        memberService.suspendMember(stranger, { orgId: tenant.org.id, memberId: owner.id }),
      ).rejects.toThrow(/at least one owner/);
      await expect(
        memberService.updateMemberRole(tenant.actors.owner, {
          orgId: tenant.org.id,
          memberId: owner.id,
          role: "admin",
        }),
      ).rejects.toThrow(/at least one owner/);
      await expect(
        memberService.removeMember(tenant.actors.owner, {
          orgId: tenant.org.id,
          memberId: owner.id,
        }),
      ).rejects.toThrow(/at least one owner/);
      expect(await statusOf(tenant, "owner")).toBe("active");

      // Reinstating the second owner frees the first.
      await memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
      });
      const demoted = await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
        role: "admin",
      });
      expect(demoted.role).toBe("admin");
    });

    it("still lets a suspended owner be removed while another owner is active", async () => {
      const tenant = await createTenant("susp-owner-remove");
      const admin = await memberOf(tenant, "admin");
      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "owner",
      });
      await suspend(tenant, "admin");

      const removed = await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
      });
      expect(removed.archivedAt).not.toBeNull();
    });
  });
});

describe("while a member is suspended", () => {
  it("cannot be resolved to an Actor and drops out of the org switcher", async () => {
    const tenant = await createTenant("susp-actor");
    const principal = {
      userId: tenant.userIds.member,
      email: "member@susp-actor.test",
      activeOrgId: tenant.org.id,
      expiresAt: "2999-01-01T00:00:00.000Z" as never,
    };

    await expect(
      memberService.resolveActor(tenant.userIds.member, tenant.org.id),
    ).resolves.toMatchObject({ role: "member" });
    await expect(orgService.listOrganizationsForUser(tenant.userIds.member)).resolves.toHaveLength(1);

    await suspend(tenant, "member");

    await expect(memberService.resolveActor(tenant.userIds.member, tenant.org.id)).resolves.toBeNull();
    await expect(sessionService.resolveActorForOrg(principal, tenant.org.slug)).resolves.toBeNull();
    await expect(orgService.listOrganizationsForUser(tenant.userIds.member)).resolves.toHaveLength(0);
    // Other members are unaffected.
    await expect(orgService.listOrganizationsForUser(tenant.userIds.admin)).resolves.toHaveLength(1);

    await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberOf(tenant, "member")).id,
    });
    await expect(orgService.listOrganizationsForUser(tenant.userIds.member)).resolves.toHaveLength(1);
    await expect(memberService.resolveActor(tenant.userIds.member, tenant.org.id)).resolves.not.toBeNull();
  });

  it("keeps their seat in every seat count; removal still frees it", async () => {
    const tenant = await createTenant("susp-seats");
    await recomputeUsage(tenant.org.id);
    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(4);

    await suspend(tenant, "viewer");

    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(4);
    expect((await recomputeUsage(tenant.org.id)).seatsUsed).toBe(4);
    const summary = await orgService.getOrganizationSummary(tenant.actors.owner, tenant.org.id);
    expect(summary.memberCount).toBe(4);
    expect(summary.usage.seatsUsed).toBe(4);

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberOf(tenant, "viewer")).id,
    });
    expect(await memberRepo.countActiveMembers(tenant.org.id)).toBe(3);
    expect((await recomputeUsage(tenant.org.id)).seatsUsed).toBe(3);
  });

  it("still counts against the invite quota", async () => {
    const tenant = await createTenant("susp-quota", "free"); // 3 seats, 4 members
    await suspend(tenant, "viewer");

    await expect(
      invitationService.inviteMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        email: "new@susp-quota.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/i);
  });

  it("is listed with status suspended", async () => {
    const tenant = await createTenant("susp-list");
    await suspend(tenant, "member");

    const page = await memberService.listMembers(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(4);
    expect(page.items.find((row) => row.userId === tenant.userIds.member)?.status).toBe("suspended");
  });

  it("receives no notification from notify() or the event fan-out", async () => {
    const tenant = await createTenant("susp-notify");
    await suspend(tenant, "member");

    const rows = await notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.member, tenant.userIds.viewer],
      PAYLOAD,
    );
    expect(rows.map((row) => row.recipientId)).toEqual([tenant.userIds.viewer]);

    // Fan-out: a comment on an issue the suspended member authored.
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Watched issue" }),
    );
    await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "ping",
      parentId: null,
      mentionedUserIds: [],
    });
    expect(await notificationsFor(tenant, tenant.userIds.member)).toHaveLength(0);

    // Reinstated: notifications flow again.
    await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberOf(tenant, "member")).id,
    });
    const after = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.member], PAYLOAD);
    expect(after).toHaveLength(1);
  });

  it("is skipped by the digest, keeping unread notifications for later", async () => {
    const tenant = await createTenant("susp-digest");
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      kind: "comment_created",
      inApp: true,
      email: false,
      digestOnly: true,
    });
    await notify(tenant.org.id, "comment_created", [tenant.userIds.member], PAYLOAD);

    const windowStart = "2000-01-01T00:00:00.000Z" as never;
    const windowEnd = "2999-01-01T00:00:00.000Z" as never;
    const digest = () => buildDigest(tenant.org.id, tenant.userIds.member, windowStart, windowEnd);

    expect(await listDigestRecipients(tenant.org.id)).toEqual([tenant.userIds.member]);
    expect(await digest()).not.toBeNull();

    await suspend(tenant, "member");
    expect(await listDigestRecipients(tenant.org.id)).toEqual([]);
    expect(await digest()).toBeNull();
    expect(
      await notificationRepo.countUnread(tenant.org.id, tenant.userIds.member),
    ).toBe(1);

    await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: (await memberOf(tenant, "member")).id,
    });
    expect(await listDigestRecipients(tenant.org.id)).toEqual([tenant.userIds.member]);
    expect((await digest())?.entries).toHaveLength(1);
  });

  it("cannot be handed new work, but keeps the issues they already have", async () => {
    const tenant = await createTenant("susp-assign");
    const owned = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already mine",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const free = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Unassigned" }),
    );
    await suspend(tenant, "viewer");

    const created = capture("issue.created");
    const assigned = capture("issue.assigned");

    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "For the suspended",
          assigneeId: tenant.userIds.viewer,
        }),
      ),
    ).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: free.id,
        assigneeId: tenant.userIds.viewer,
      }),
    ).rejects.toMatchObject({ code: "conflict" });

    expect(created).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    const page = await issueService.listIssues(tenant.actors.member, {
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
      includeArchived: false,
    });
    expect(page.items.map((issue) => issue.title)).not.toContain("For the suspended");
    expect(
      (await issueService.getIssue(tenant.actors.member, tenant.org.id, free.id)).issue.assigneeId,
    ).toBeNull();

    // Existing work stays; un-assigning and assigning to an active member work.
    expect(
      (await issueService.getIssue(tenant.actors.member, tenant.org.id, owned.id)).issue.assigneeId,
    ).toBe(tenant.userIds.viewer);
    const reassigned = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: owned.id,
      assigneeId: tenant.userIds.admin,
    });
    expect(reassigned.assigneeId).toBe(tenant.userIds.admin);
    const cleared = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: owned.id,
      assigneeId: null,
    });
    expect(cleared.assigneeId).toBeNull();
  });

  it("cannot be mentioned by handle or by a client-supplied id", async () => {
    const tenant = await createTenant("susp-mention");
    await suspend(tenant, "admin");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Discuss" }),
    );
    const created = capture("comment.created");

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "cc @admin and @owner",
      parentId: null,
      mentionedUserIds: [tenant.userIds.admin, tenant.userIds.viewer],
    });

    const expected = [tenant.userIds.owner, tenant.userIds.viewer];
    expect(created[0]?.mentionedUserIds).toEqual(expected);
    expect(comment.mentionedUserIds).toEqual(expected);
    expect(
      await notificationsFor(tenant, tenant.userIds.admin),
    ).toHaveLength(0);
  });

  it("a removed member is not a suspended one", async () => {
    const tenant = await createTenant("susp-removed-not");
    const viewer = await memberOf(tenant, "viewer");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    // Removed members are not treated as suspended: notify() behaves as before.
    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.viewer], PAYLOAD);
    expect(rows).toHaveLength(1);
    await expect(memberService.assertMemberNotSuspended(tenant.org.id, tenant.userIds.viewer)).resolves.toBeUndefined();
  });
});

